const clone=structuredClone;
const request=actual.responses.manual_put.request;
const settings=()=>({aspect_ratio:request.aspect_ratio,points:clone(request.points)});
function state(role='editor') {
 const timeline=clone(actual.responses.manual_before.body.timeline), p=actual.responses.manual_before.body.source;
 const measured={media_kind:'video',duration_seconds:p.duration_seconds,audio_codec:p.has_audio?'aac':null,width:p.width,height:p.height,fps:p.fps};
 const asset={asset_id:p.asset_id,workspace_id:timeline.workspace_id,project_id:timeline.project_id,asset_class:'source',kind:'video',content_type:'video/mp4',
  checksum_sha256:p.source_sha256,size_bytes:4096,object_key:p.object_key,provenance:{source_type:'user_upload',media_metadata:clone(measured)}};
 const analysis={analysis_id:p.analysis_id,asset_id:p.asset_id,workspace_id:timeline.workspace_id,project_id:timeline.project_id,status:'succeeded',
  fingerprint:p.analysis_fingerprint,source_media:measured,source_media_mutated:false,publish_requested:false,configuration:{asset_id:p.asset_id}};
 return{workspaceId:timeline.workspace_id,projectId:timeline.project_id,timeline,assets:[asset],analysis,busy:false,dirty:false,
  principal:{...clone(actual.responses.session.body),expires_at:'2100-01-01T00:00:00Z',workspace_roles:{[timeline.workspace_id]:role}}};
}
function harness({s=state(),handler,storage,crypto,onSaved,onRead,memory=new Map()}={}) {
 class Element {constructor(tag){this.tagName=tag;this.children=[];this.attributes={};this.listeners={};this.textContent='';this.disabled=false;}
  append(...v){this.children.push(...v);}setAttribute(k,v){this.attributes[k]=String(v);}addEventListener(k,f){this.listeners[k]=f;}}
 const root=new Element('section'),dom={createElement:tag=>new Element(tag)},all=e=>[e,...e.children.flatMap(all)];
 const get=name=>all(root).find(e=>Object.hasOwn(e.attributes,'data-manual-reframe-'+name));
 const calls=[],saved=[],reads=[],messages=[];let token='EXPLICIT_TRANSIENT_MANUAL_TEST_TOKEN',response=clone(actual.responses.manual_before.body);
 const result=body=>{const data=clone(actual.responses.manual_put.body);data.receipt.request_key=body.request_key;return data;};
 const api=async(path,options)=>{const c={path,method:options?.method??'GET',body:options?.body?JSON.parse(options.body):null};calls.push(c);
  if(handler)return handler(c,{result,setResponse:value=>{response=clone(value);}});if(c.method==='PUT')response=result(c.body);return clone(response);};
 const backing=storage??{getItem:k=>memory.get(k)??null,setItem:(k,v)=>memory.set(k,v),
  compareAndRemoveItem:(k,exact)=>{if(memory.get(k)!==exact)return false;memory.delete(k);return true;}};
 const controller=initializeSqlManualReframe({root,dom,api,getState:()=>s,storage:backing,cryptoImpl:crypto??webcrypto,
  newRequestKey:()=>request.request_key,getSessionToken:()=>token,onMessage:(...v)=>messages.push(v),
  onRead:async value=>{reads.push(value);if(onRead)return onRead(value,s);},
  onSaved:async (value,guard)=>{saved.push(value);if(onSaved)return onSaved(value,s,guard);s.timeline=clone(value.timeline);}});
 return{controller,calls,saved,reads,s,memory,get,messages,result,setToken:v=>{token=v;},run:(v=settings(),o={acknowledged:true})=>controller.runSettings(v,o)};
}
test('private synchronous callback guard rejects foreign raw, checks scope after storage and is revoked',async()=>{
 for(const change of ['foreign','storage-source','none']){
  const memory=new Map();let h,armed=false,guardRef;
  const storage={getItem:k=>{const raw=memory.get(k)??null;if(armed&&change==='storage-source')h.s.assets[0].checksum_sha256='f'.repeat(64);return raw;},
   setItem:(k,v)=>memory.set(k,v),compareAndRemoveItem:(k,v)=>{if(memory.get(k)!==v)return false;memory.delete(k);return true;}};
  h=harness({storage,onSaved:async(value,s,guard)=>{guardRef=guard;assert.equal(guard(),true);await Promise.resolve();
   if(change==='foreign'){const[k,raw]=[...memory][0];const b=JSON.parse(raw);b.body.request_key='foreign-callback-request-B';memory.set(k,JSON.stringify(b));}
   armed=true;if(change==='none'){assert.equal(guard(),true);s.timeline=clone(value.timeline);}else assert.throws(()=>guard());}});
  const before=clone(h.s.timeline);assert.equal(Boolean(await h.run()),change==='none');assert.throws(()=>guardRef());
  assert.equal(h.calls.filter(c=>c.method==='PUT').length,1);
  if(change!=='none'){assert.deepEqual(h.s.timeline,before);assert.equal(memory.size,1);assert.equal(h.controller.isPending(),true);}
 }
});
