test('caller settings are frozen before awaited GET, preserving original body and source hash',async()=>{
 let release,entered;const waiting=new Promise(r=>{release=r;}),started=new Promise(r=>{entered=r;});
 const h=harness({handler:async(c,tools)=>{if(c.method==='GET'){entered();await waiting;return clone(actual.responses.manual_before.body);}return tools.result(c.body);}});
 const v=settings(),pending=h.run(v);await started;v.points[0].x=.7;v.points.push({time:15,x:.5,y:.5,zoom:4});release();
 assert.equal(await pending,true);assert.deepEqual(h.calls[1].body,request);
});
for(const field of['token','analysis','asset','transcript','dirty','timeline']){
 test(`onRead awaited callback drift ${field} prevents a stale read view and new PUT`,async()=>{
  let h;h=harness({onRead:async()=>{await Promise.resolve();drift(h,field);}});
  await assert.rejects(h.controller.reload());assert.equal(h.calls.length,1);assert.equal(h.saved.length,0);assert.equal(h.memory.size,0);
 });
}
function drift(h,field){
 if(field==='token')h.setToken('DIFFERENT_TRANSIENT_MANUAL_TEST_TOKEN');
 else if(field==='analysis')h.s.analysis.fingerprint='e'.repeat(64);
 else if(field==='asset')h.s.assets[0].filename='changed-name.mp4';
 else if(field==='transcript')h.s.timeline.snapshot.metadata.transcript_revision.version++;
 else if(field==='dirty')h.s.dirty=true;
 else h.s.timeline.current_version++;
}
for(const field of['token','analysis','asset','transcript','dirty','timeline']){
 test(`fourth digest after installation drift ${field} retains exact UNKNOWN and never compare-removes`,async()=>{
  let h,count=0,removed=0;const memory=new Map();const crypto={subtle:{digest:async(...args)=>{const value=await webcrypto.subtle.digest(...args);if(++count===4)drift(h,field);return value;}}};
  h=harness({memory,crypto,storage:{getItem:k=>memory.get(k)??null,setItem:(k,v)=>memory.set(k,v),compareAndRemoveItem:()=>{removed++;return true;}}});
  assert.equal(await h.run(),false);assert.equal(h.calls.filter(c=>c.method==='PUT').length,1);assert.equal(memory.size,1);
  assert.equal(h.controller.isPending(),true);assert.equal(removed,0);
 });
}
test('storage getItem callback source drift retains exact UNKNOWN instead of compare-removing',async()=>{
 let h,n=0,removed=0;const memory=new Map();h=harness({memory,storage:{getItem:k=>{const v=memory.get(k)??null;
  if(v&&++n===2)h.s.analysis.fingerprint='d'.repeat(64);return v;},setItem:(k,v)=>memory.set(k,v),compareAndRemoveItem:()=>{removed++;return true;}}});
 assert.equal(await h.run(),false);assert.equal(memory.size,1);assert.equal(h.controller.isPending(),true);assert.equal(removed,0);
});
test('callback that does not install exact returned timeline keeps UNKNOWN',async()=>{
 const h=harness({onSaved:()=>{}});assert.equal(await h.run(),false);assert.equal(h.saved.length,1);assert.equal(h.memory.size,1);assert.equal(h.controller.isPending(),true);
});
test('callback changing independent asset metadata cannot release UNKNOWN after installing result',async()=>{
 const h=harness({onSaved:(v,s)=>{s.timeline=clone(v.timeline);s.assets[0].filename='changed.mp4';}});
 assert.equal(await h.run(),false);assert.equal(h.memory.size,1);assert.equal(h.controller.isPending(),true);
});
test('lost committed PUT reconciles through exact receipt, never submits a second intent',async()=>{
 let committed=false;const h=harness({handler:(c,tools)=>{if(c.method==='PUT'){committed=true;throw Error('lost committed response');}
  return clone(committed?actual.responses.manual_put.body:actual.responses.manual_before.body);}});
 assert.equal(await h.run(),false);assert.equal(h.controller.isPending(),true);assert.equal(h.memory.size,1);
 await h.controller.reconcile();assert.equal(h.controller.isPending(),false);assert.equal(h.memory.size,0);assert.equal(h.calls.filter(c=>c.method==='PUT').length,1);
});
test('lost uncommitted PUT requires explicit reconcile then identical retry with same body and key',async()=>{
 let first=true;const h=harness({handler:(c,tools)=>{if(c.method==='GET')return clone(actual.responses.manual_before.body);
  if(first){first=false;throw Error('lost before commit');}return tools.result(c.body);}});
 assert.equal(await h.run(),false);await assert.rejects(h.controller.retry());assert.equal(h.calls.filter(c=>c.method==='PUT').length,1);
 await h.controller.reconcile();await h.controller.retry();assert.deepEqual(h.calls.filter(c=>c.method==='PUT').map(c=>c.body),[request,request]);assert.equal(h.memory.size,0);
});
test('cold reload does not auto-write and restores exact parent plus original source/token evidence',async()=>{
 const memory=new Map(),first=harness({memory,handler:c=>{if(c.method==='PUT')throw Error('offline');return clone(actual.responses.manual_before.body);}});
 assert.equal(await first.run(),false);const [key,raw]=[...memory][0];
 const next=harness({memory});assert.equal(next.calls.length,0);assert.equal(next.controller.isPending(),true);await next.controller.reload();
 assert.equal(memory.get(key),raw);assert.equal(next.calls.filter(c=>c.method==='PUT').length,0);
 await next.controller.reconcile();await next.controller.retry();assert.equal(next.memory.size,0);assert.deepEqual(next.calls.find(c=>c.method==='PUT').body,request);
});
test('untrusted malformed durable record is retained and cannot cause read-driven PUT or removal',async()=>{
 const first=harness({handler:c=>{if(c.method==='PUT')throw Error('offline');return clone(actual.responses.manual_before.body);}});await first.run();
 const [key]=[...first.memory][0],memory=new Map([[key,'{"schema_version":"forged"}']]),h=harness({memory});
 await assert.rejects(h.controller.reload());await assert.rejects(h.controller.retry());assert.equal(h.calls.length,0);assert.equal(memory.size,1);assert.equal(h.controller.isPending(),true);
});
test('server source binding drift during reconciliation forbids exact retry and keeps original record',async()=>{
 let lost=false;const h=harness({handler:c=>{if(c.method==='PUT'){lost=true;throw Error('offline');}
  const v=clone(actual.responses.manual_before.body);if(lost)v.source_binding_sha256='a'.repeat(64);return v;}});
 assert.equal(await h.run(),false);await assert.rejects(h.controller.reconcile());await assert.rejects(h.controller.retry());assert.equal(h.memory.size,1);assert.equal(h.calls.filter(c=>c.method==='PUT').length,1);
});
test('foreign storage replacement during callback is preserved byte-exact and never removed',async()=>{
 const h=harness({onSaved:(v,s)=>{s.timeline=clone(v.timeline);for(const key of h.memory.keys())h.memory.set(key,'FOREIGN_REPLACEMENT');}});
 assert.equal(await h.run(),false);assert.deepEqual([...h.memory.values()],['FOREIGN_REPLACEMENT']);assert.equal(h.controller.isPending(),true);
});
test('mismatched settings, applied keyframes, source scope or elevated result flags remain UNKNOWN',async()=>{
 for(const mutate of[v=>{v.settings.points[0].x=.9;},v=>{v.receipt.applied_keyframes[0].time=1;},v=>{v.source.fps++;},v=>{v.source_binding_sha256='f'.repeat(64);},
  v=>{v.receipt.actor_ref='usr:other';},v=>{v.timeline.publish_requested=true;},v=>{v.receipt.source.source_sha256='d'.repeat(64);},v=>{v.receipt.extra=true;}]){
  const h=harness({handler:(c,tools)=>{if(c.method==='GET')return clone(actual.responses.manual_before.body);const v=tools.result(c.body);mutate(v);return v;}});
  assert.equal(await h.run(),false);assert.equal(h.memory.size,1);assert.equal(h.saved.length,0);assert.equal(h.controller.isPending(),true);
 }
});
test('disposal before awaited GET prevents every write and durable record',async()=>{
 let release,entered;const wait=new Promise(r=>{release=r;}),started=new Promise(r=>{entered=r;});const h=harness({handler:async()=>{entered();await wait;return clone(actual.responses.manual_before.body);}});
 const pending=h.run();await started;h.controller.dispose();release();assert.equal(await pending,false);assert.equal(h.calls.length,1);assert.equal(h.memory.size,0);
});

test('matching receipt/snapshot but wrong manual geometry is rejected before onSaved',async()=>{
 const h=harness({handler:(c,tools)=>{if(c.method==='GET')return clone(actual.responses.manual_before.body);
  const v=tools.result(c.body);v.receipt.applied_keyframes[0].x+=.01;
  for(const t of v.timeline.snapshot.tracks)if(t.kind==='source')for(const clip of t.clips)clip.metadata.reframe.keyframes[0].x+=.01;
  return v;}});
 assert.equal(await h.run(),false);assert.equal(h.saved.length,0);assert.equal(h.memory.size,1);
});
test('getter-coerced coordinate cannot change to invalid value between preflight and frozen intent',async()=>{
 const v=settings();let reads=0;Object.defineProperty(v.points[0],'x',{enumerable:true,get:()=>++reads===1?.2:'not-a-number'});
 const h=harness();assert.equal(await h.run(v),false);assert.equal(h.calls.length,0);assert.equal(h.memory.size,0);
});
